// Count what every department did today, straight from the shared sheet.
const today = $now.toISODate();
const rows = (n) => { try { return $(n).all().map((i) => i.json).filter((r) => Object.keys(r).length); } catch (e) { return []; } };
const isToday = (r) => String(r.Date || '').startsWith(today);
const num = (v) => Number(String(v ?? '').replace(/[^0-9.\-]/g, '')) || 0;
const leads = rows('Manager · Read Leads').filter(isToday);
const inbound = leads.filter((r) => r.Status !== 'prospect');
const reviews = rows('Manager · Read Reviews').filter(isToday);
const bills = rows('Manager · Read Bills').filter(isToday);
const overdue = rows('Manager · Read Invoices').filter((r) => String(r.Status).toLowerCase() !== 'paid' && r['Due date'] && String(r['Due date']) < today);
const cands = rows('Manager · Read Candidates').filter(isToday);
return [{ json: {
  date: today,
  sales: { new_leads: inbound.length, hot: inbound.filter((r) => String(r.Status).toLowerCase() === 'hot').map((r) => `${r.Name || r.Phone} (${r.Source})`),
           prospects_found: leads.length - inbound.length },
  support: { bookings: rows('Manager · Read Bookings').filter(isToday).map((r) => `${r.Name} ${r.Start}`) },
  marketing: { content_made: rows('Manager · Read Content').filter(isToday).map((r) => `${r.Type}: ${r.Title}`),
               reviews: reviews.length, angry_reviews: reviews.filter((r) => r.Sentiment === 'angry').map((r) => `${r.Reviewer} ${r.Stars}★`) },
  ops: { bills_today: bills.length, bills_total: bills.reduce((s, r) => s + num(r.amount), 0),
         overdue_invoices: overdue.length, overdue_total: overdue.reduce((s, r) => s + num(r.Amount), 0),
         shortlisted: cands.filter((r) => r.Status === 'Shortlist').map((r) => `${r.Name} (${r.Score}/10)`) },
} }];

return ($input.first().json.places || [])
  .filter(p => p.websiteUri)
