return $input.all().map((item, i) => {
  const biz = $('Lead Finder · One row per business').all()[i].json;
  const html = String(item.json.data || '');
  const title = (html.match(/<title[^>]*>([^<]*)/i) || [])[1] || '';
  const text = html.replace(/<script[\s\S]*?<\/script>|<style[\s\S]*?<\/style>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim().slice(0, 2500);
  const signals = { online_booking: /book (online|now)|appointment/i.test(html), chat_widget: /intercom|tawk|crisp|livechat|whatsapp/i.test(html) };
  return { json: { ...biz, title, text, signals } };
});

