// Leads arrive from the form/ads webhook, the WhatsApp Replier and the Missed-Call Rescuer.
const leads = $('Qualifier · Lead in').all();
return $input.all().map((item, i) => {
  let lead;
  try { lead = $('Qualifier · Lead in').itemMatching(i).json.body; } catch (e) { lead = leads[i]?.json.body; }
  lead = lead ?? {};
  const tool = (item.json.content ?? []).find((c) => c.type === 'tool_use');
  const q = tool?.input ?? {};
  const ok = ['hot', 'warm', 'cold'].includes(q.status);
  return {
    json: {
      Date: $now.toISODate(),
      Source: lead.source ?? 'Form / Ads',
      Name: lead.name ?? '',
      Phone: lead.phone ?? '',
      Email: lead.email ?? '',
      Message: lead.message ?? '',
      Status: ok ? q.status : 'warm',
      Reason: ok ? q.reason ?? '' : 'AI qualification failed - review manually',
    },
  };
});

