const today = $now.startOf('day');
const out = [];
for (const { json: r } of $input.all()) {
  if (String(r['Status']).toLowerCase() === 'paid' || !r['Due date'] || !r['Email']) continue;
  const days = Math.floor(today.diff(DateTime.fromISO(String(r['Due date'])), 'days').days);
  if (days < 1) continue;
  if (r['Last reminder'] === today.toISODate()) continue;
  const tone = days <= 7 ? 'friendly' : days <= 21 ? 'firm' : 'final';
  out.push({ json: { ...r, days_overdue: days, tone, reminders: Number(r['Reminders sent'] || 0) } });
}
return out;

